mapper.select:
select ph.photo_id, ph.cat_id, ph.folder, ph.file_type, ph.file_url, ph.thumb_url,
       ph.create_by, ph.create_time, ph.update_by, ph.update_time, ph.remark,
       p.cat_name, p.archive_no, p.breed, p.sex, p.base_id, p.ward_id,
       b.base_name, w.ward_name
  from cat_photo ph
  left join cat_profile p on p.cat_id = ph.cat_id
  left join cat_base b on b.base_id = p.base_id
  left join cat_ward w on w.ward_id = p.ward_id

    AND ph.cat_id = #{catId}
    AND ph.folder = #{folder}
    AND ph.file_type = #{fileType}
    AND ph.file_url = #{fileUrl}

    AND p.breed = #{breed}
    AND p.sex = #{sex}
    AND p.base_id = #{baseId}
    AND p.ward_id = #{wardId}

order by ph.create_time desc, ph.photo_id desc

select p.cat_id as catId, p.cat_name as catName, p.archive_no as archiveNo,
       p.breed as breed, p.sex as sex, p.base_id as baseId, p.ward_id as wardId,
       b.base_name as baseName, w.ward_name as wardName,
       (select count(*) from cat_photo x where x.cat_id = p.cat_id
         and x.folder = #{folder}
         and x.file_type = #{fileType}
       ) as photoCount,
       (select coalesce(nullif(x.thumb_url, ''), x.file_url)
          from cat_photo x
         where x.cat_id = p.cat_id
         and x.folder = #{folder}
         and x.file_type = #{fileType}
         order by x.create_time desc, x.photo_id desc limit 1) as coverUrl,
       (select x.create_time from cat_photo x
         where x.cat_id = p.cat_id
         and x.folder = #{folder}
         and x.file_type = #{fileType}
         order by x.create_time desc, x.photo_id desc limit 1) as latestTime
  from cat_profile p
  left join cat_base b on b.base_id = p.base_id
  left join cat_ward w on w.ward_id = p.ward_id

    p.del_flag = '0'
    and exists (select 1 from cat_photo x where x.cat_id = p.cat_id
                and x.folder = #{folder}
                and x.file_type = #{fileType}
               )
    AND p.cat_id = #{catId}
    AND p.breed = #{breed}
    AND p.sex = #{sex}
    AND p.base_id = #{baseId}
    AND p.ward_id = #{wardId}

order by latestTime desc
